INSERT INTO base_docs (titulo, categoria, responsavel, steps, nota) VALUES
('SOP — Abertura e Qualificação de Lead', 'SOPs', 'Atendimento', '["Cumprimentar, perguntar o nome e o que motivou o contato (projeto específico ou curiosidade sobre produto do anúncio)", "Perguntar se é para projeto próprio, cliente de arquitetura/construção ou revenda antes de indicar linha e preço", "\\"Quanto custa?\\": informar a faixa de preço por m² da linha perguntada e sempre complementar que pode variar por quantidade e região — consultor confirma o valor final", "\\"Por que é mais caro?\\": explicar que a Bruto não fabrica em massa — é curadoria de peças artesanais batidas à mão, com parceria direta de fábrica", "\\"Tem pronta entrega?\\": ser honesto — prazo total de 7 a 15 dias úteis (já inclui produção e frete). A equipe confirma uma data exata em até 3 dias úteis", "Amostra: oferecer até 3 peças, mas SEMPRE deixar claro que o frete da amostra não é grátis — varia por região e é confirmado antes do envio. Nunca dizer \\"amostra grátis\\"", "Indeciso entre produtos: perguntar onde vai aplicar (interno/externo, destaque ou discreto) antes de recomendar", "Lead frio que só quer catálogo/preço: enviar a faixa de preço e convidar para o WhatsApp oficial, sem forçar continuidade"]', 'A meta da primeira conversa é qualificar o interesse e manter o relacionamento (amostra, WhatsApp, projeto) — não fechar preço definitivo no primeiro contato.'),
('Política — Quando Escalar para o Responsável', 'Políticas', 'Gestão', '["Pedido grande/B2B — construtoras ou revendedores pedindo volume alto ou condição comercial diferenciada (preço e prazo não seguem o catálogo padrão)", "Desconto além do publicado — nunca conceder ou prometer desconto por conta própria", "Ameaça de ação legal ou Procon — escalar imediatamente, sem debater o mérito pelo chat", "Defeito de fabricação contestado — cliente insiste e a KB não é conclusiva, ou o caso foge do padrão (rachadura, problema estrutural)", "Pergunta técnica fora do que a KB cobre — não inventar resposta técnica definitiva, confirmar com a fábrica parceira", "Contato de imprensa, influenciador ou proposta de parceria", "Reclamação pública ou emocionalmente tensa — prioridade é acalmar e direcionar para atendimento humano"]', 'Regra de ouro: nunca prometer preço final, desconto, prazo exato ou resolução de disputa sem confirmação. Mais seguro dizer "vou confirmar com o time e te retorno" do que improvisar.'),
('Política — Frete, Entrega e Amostras', 'Políticas', 'Atendimento', '["Prazo total de entrega: 7 a 15 dias úteis — esse número já inclui produção/separação e frete, não são prazos somados", "A equipe tem até 3 dias úteis após o pedido pra confirmar uma data específica dentro dessa faixa — isso não é o prazo de entrega em si, é o prazo pra dar uma data exata", "Entrega própria só na Grande São Paulo. Fora da Grande SP, avaliar caso a caso — pedidos grandes costumam compensar o frete maior", "Amostra física: até 3 por pedido, combinadas pelo site ou WhatsApp — mas o frete da amostra NÃO é grátis, varia por região e é confirmado antes do envio", "Nunca prometer entrega mais rápida pra fechar venda — gera reclamação depois"]', 'Nunca confundir os dois prazos numa mesma resposta: 3 dias úteis é só a confirmação da data exata, 7 a 15 dias úteis é a entrega completa.'),
('Política — Variação Natural e Devolução', 'Políticas', 'Atendimento', '["Identificar o motivo do pedido: arrependimento (dentro de 7 dias, sem uso) vs. defeito de fabricação", "Para defeito: pedir registro fotográfico e encaminhar para análise da equipe antes de prometer troca", "Nunca tratar variação natural de tom/textura como defeito — explicar que é característica esperada do processo artesanal", "Frete, prazos e condições finais de troca são sempre confirmados por um consultor"]', 'Peças batidas à mão e retificadas individualmente têm pequenas variações de tom e textura entre lotes — isso está nos Termos de Uso oficiais e não gera direito a troca por esse motivo.'),
('SOP — Cadência de Follow-up', 'Processos', 'Atendimento', '["D+1 · WhatsApp — confirmar que recebeu o orçamento/amostra e tirar dúvida técnica", "D+3 · WhatsApp — oferecer amostra física se ainda não pediu (é o que segura o lead enquanto ele decide)", "D+7 · Ligação — entender em que estágio está o projeto. Ligação tem retorno melhor que texto nesse ponto", "D+14 · WhatsApp — mandar aplicação real parecida com o projeto dele, sem cobrar resposta", "D+30 · WhatsApp — checar se a obra saiu do papel", "Parar a cadência quando o cliente responder que desistiu, escolheu outro fornecedor ou pedir para não receber mais contato", "Registrar cada toque no UP·Lead — sem registro, a cadência se perde entre atendentes"]', 'Venda por especificação morre de silêncio, não de objeção. Referência de mercado: a maior taxa de conversão acontece a partir do 7º contato, mas quase metade das empresas não faz nem o primeiro follow-up e só cerca de 10% passam de três. Ou seja: quem faz cadência disputa com pouca gente.'),
('Referência — Catálogo e Faixas de Preço', 'Vendas', 'Atendimento', '["Brick — 11 modelos, R$ 104,90 a R$ 197,90/m². Interno e externo. Natura é a entrada de linha; Rusticatto Terra Negra o topo", "Cimentício — 3 modelos (Alpino, Brisa, Urban), R$ 186,90/m². Interno e externo, visual liso contemporâneo", "Rockface — 3 modelos (Brisa, Alpino, Urban), R$ 186,90 a R$ 252,90/m². EXCLUSIVAMENTE externo — nunca indicar para área interna", "Preços do site estão sujeitos a alteração e variam por quantidade, região e condição comercial vigente", "A confirmação final de valor, prazo e forma de pagamento é sempre de um consultor — nunca fechar condição pelo chat"]', 'Rusticatto (Fumê, Palha, Rosso, Sertão, Terra Negra) tem espessura maior que os demais Brick — relevante para cálculo de argamassa e transição de nível com outros pisos.'),
('SOP — Controle de Amostras', 'Operação', 'Atendimento', '["Registrar QUAIS modelos foram enviados, não apenas \\"3 amostras\\" — sem isso não dá pra saber qual peça consome amostra sem virar venda", "Confirmar o frete com o cliente ANTES do envio. Nunca dizer que a amostra é grátis: a peça é cortesia dentro do limite de 3, o frete não é", "Lançar o custo das peças no UP·Vault na categoria Amostras — é custo real de aquisição de cliente, não despesa diluída em \\"Outros\\"", "Marcar o lead como etapa \\"Amostra enviada\\" no UP·Lead na mesma hora — é o que dispara o follow-up de D+7", "Se não houver retorno em 7 dias, puxar contato leve perguntando o que achou. Amostra entregue e esquecida é dinheiro parado na casa do cliente", "Ao fechar ou perder o lead, registrar o desfecho — é isso que permite descobrir depois quais modelos convertem e quais só drenam"]', 'São 17 modelos no catálogo e cada amostra despachada é peça real com custo. Um modelo que gera amostra e nunca fecha só aparece somando meses — por isso o registro por modelo é obrigatório, não opcional.'),
('SOP — Convenções de Deploy e Segurança', 'Processos', 'Dev', '["Nunca fazer git push sem mostrar o diff e pedir confirmação explícita antes — o deploy é automático, um push errado vai direto pro site ao vivo", "Usar sempre o formato GIT_ASKPASS=/bin/true com token de acesso — o formato simples de URL com token falha de forma confusa", "Todo endpoint público (api/*.php) precisa de autenticação, no mínimo HTTP Basic Auth de pasta/subdomínio", "Segredos (chave de API, senha de banco, números reais de WhatsApp) ficam em bruto-secrets/, fora do alcance do Git — nunca commitados", "Subdomínios próprios seguem pasta isolada, nunca usando public_html da raiz"]', 'Já corrigimos uma ferramenta (Ordem de Serviço) que estava completamente aberta, sem senha, indexável pelo Google — segurança em primeiro lugar em qualquer ferramenta nova.');
